x = 1:32;
y = x.^2;

plot(x, y, 'o-r', x, y/3, 'xb') %[output:7c06e2f5]
title('Dvi funkcijos') %[output:7c06e2f5]
xlabel('x-ai') %[output:7c06e2f5]
ylabel('F_1 [-o-]   |   F_2 [-x-]') %[output:7c06e2f5]
