% Papildoma užduotis

N = 8;
a = N+1:1/2:N+4 %[output:9930d531]

A = reshape(N:N+8, 3, 3)' %[output:789a110a]
A(3, 2) %[output:9a46d226]
A(2:3,1:2) %[output:529b0620]
A([1 3 7 9]) %[output:47c4981e]

a_mod = [a, zeros(1, 9 - numel(a))] %[output:34b1a3a4]
b = reshape(a_mod, 3, 3) %[output:3b7f36f2]

B = [A b] %[output:46e105d6]

